from typing import List


class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        mod = 10**9 + 7
        n = len(num)
        digits = [int(c) for c in num]
        total = sum(digits)
        if total % 2:
            return 0
        target = total // 2
        even = (n + 1) // 2
        odd = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (n + 1)
        inv[n] = pow(fact[n], mod - 2, mod)
        for i in range(n, 0, -1):
            inv[i - 1] = inv[i] * i % mod
        cnt = [0] * 10
        for d in digits:
            cnt[d] += 1
        dp = [[0] * (target + 1) for _ in range(even + 1)]
        dp[0][0] = 1
        for d in range(10):
            c = cnt[d]
            if c == 0:
                continue
            new = [[0] * (target + 1) for _ in range(even + 1)]
            for j in range(even + 1):
                row = dp[j]
                for s in range(target + 1):
                    val = row[s]
                    if val == 0:
                        continue
                    for a in range(c + 1):
                        nj = j + a
                        ns = s + a * d
                        if nj > even or ns > target:
                            break
                        new[nj][ns] = (new[nj][ns] + val * inv[a] % mod * inv[c - a]) % mod
            dp = new
        return dp[even][target] * fact[even] % mod * fact[odd] % mod

